def forecast(history: list[float], horizon: int, frequency: str) -> list[float]:
    x = [float(v) for v in history]
    n = len(x)
    if horizon <= 0:
        return []
    if n == 0:
        return [0.0] * horizon
    f = frequency.lower()
    p = 24 if 'hour' in f else (7 if 'day' in f else 1)
    p = max(1, min(p, n))
    ordered = sorted(x)
    med = ordered[n // 2] if n % 2 else 0.5 * (ordered[n // 2 - 1] + ordered[n // 2])
    window = min(max(4, p), n)
    recent_mean = sum(x[-window:]) / window
    candidates = ['seasonal', 'level', 'median', 'zero']
    scores = {}
    start = max(1, n - min(n - 1, 2 * p))
    for name in candidates:
        total = 0.0
        weight = 0.0
        for t in range(start, n):
            if name == 'seasonal':
                if t < p:
                    continue
                pred = x[t - p]
            elif name == 'level':
                lo = max(0, t - window)
                pred = sum(x[lo:t]) / max(1, t - lo)
            elif name == 'median':
                prior = sorted(x[:t])
                pred = prior[len(prior) // 2]
            else:
                pred = 0.0
            actual = x[t]
            w = 1.0 + (t - start) / max(1, n - start)
            total += w * abs(actual - pred) / (1.0 + abs(actual) + abs(pred))
            weight += w
        scores[name] = total / weight if weight else float('inf')
    chosen = min(candidates, key=lambda z: scores[z])
    out = []
    for i in range(horizon):
        if chosen == 'seasonal':
            v = x[(n + i - p) % n] if i < p else out[i - p]
        elif chosen == 'level':
            v = recent_mean
        elif chosen == 'median':
            v = med
        else:
            v = 0.0
        if v != v or abs(v) == float('inf'):
            v = 0.0
        out.append(float(v))
    return out
